// Consistent hashing for shard routing
class ConsistentHashRing {
  constructor(shards, virtualNodes = 150) {
    this.ring = new SortedMap();
    for (const shard of shards) {
      for (let i = 0; i < virtualNodes; i++) {
        const key = hash(`${shard.id}:${i}`);
        this.ring.set(key, shard);
      }
    }
  }

  getShard(entityId) {
    const key = hash(entityId);
    // Find the first shard clockwise from the key
    return this.ring.ceilingEntry(key)?.value 
      ?? this.ring.firstEntry().value;
  }
}

// Cache-aside with distributed lock to prevent stampede
async function getCachedUser(userId: string) {
  const cacheKey = `user:${userId}`;
  const cached = await redis.get(cacheKey);
  if (cached) return JSON.parse(cached);

  // Distributed lock prevents stampede
  const lockKey = `lock:user:${userId}`;
  const acquired = await redis.set(lockKey, '1', 'NX', 'EX', 5);

  if (!acquired) {
    // Another instance is fetching — wait and retry
    await sleep(100);
    return getCachedUser(userId);
  }

  try {
    const user = await db.users.findById(userId);
    await redis.setex(cacheKey, 300, JSON.stringify(user));
    return user;
  } finally {
    await redis.del(lockKey);
  }
}
